"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["73647"],{91612(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.fase_cronograma.tipo_banca_nao_encontrado","status":422,"titulo":"Tipo de banca n\xe3o encontrado ou n\xe3o est\xe1 mais vivo"},"descricao":{"codigo":"uniplus.selecao.fase_cronograma.tipo_banca_nao_encontrado","requisitos":[],"oQueAconteceu":["A fase do cronograma declara as bancas que atuam nela (`bancasRequeridas`), e\\ncada banca \xe9 de um tipo do cadastro do m\xf3dulo Configura\xe7\xe3o. O pedido de defini\xe7\xe3o\\ndo cronograma (`PUT .../cronograma-fases`) citou, em\\n`fases[n].bancasRequeridas[m].tipoBancaId`, um identificador que n\xe3o corresponde a\\nnenhum tipo de banca, ou que corresponde a um tipo removido do cadastro. A\\nmensagem traz o identificador.","O tipo de banca \xe9 copiado por valor para o cronograma, e sem ele a banca n\xe3o pode\\nser montada. A confer\xeancia segue pelas demais bancas da mesma fase, e as recusas\\ndelas se somam a esta no array `errors[]`; em seguida a **montagem do cronograma\\n\xe9 interrompida** nessa fase: as fases anteriores da lista, com as viola\xe7\xf5es que j\xe1\\ntiveram, saem na mesma resposta, e as seguintes n\xe3o chegam a ser conferidas. Nada\\n\xe9 gravado."],"comoResolver":["Confira, no cadastro de tipos de banca do m\xf3dulo Configura\xe7\xe3o, o identificador do\\ntipo pretendido e use-o em `tipoBancaId`. Se o tipo foi removido do cadastro e\\nainda deve existir, pe\xe7a a quem o gere que o restabele\xe7a antes de repetir a\\ndefini\xe7\xe3o do cronograma. Corrija tamb\xe9m as demais viola\xe7\xf5es que a resposta trouxer."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Fase cronograma"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);